message.content:
{
  "description": "The creature is a quadrupedal hybrid shown in right-facing profile standing on a small patch of pale ground. It has the furry head of a brown bear at the front and the rest of the body covered in a dark, glossy, heavily segmented exoskeleton resembling a beetle or woodlouse. The exoskeleton is dark brown to black and shiny, with large overlapping plates over the back, neck, sides, belly and all four thick legs, and a tapering segmented tail at the rear. A single large curved horn with a notch on its underside projects forward from the armored plate on the neck over the top of the bear's head. The bear fur is medium brown with a lighter tan muzzle, black nose and dark eyes, contrasting with the dark armor. The four legs are stout and columnar, ending in clawed feet, and the overall posture is that of a standing mammal.",
  "parts": [
    {
      "part": "head",
      "looks_like": "furry bear head with a long tan muzzle, black nose at the tip, dark brown eyes on the sides, and a closed mouth; fur is brown and dense around the cheeks and neck",
      "where": "at the extreme front of the body, facing right, with the neck joining the armored torso behind it"
    },
    {
      "part": "horns",
      "looks_like": "one large glossy dark brown to black horn, smooth and curved forward with a pointed tip and a small pointed notch on the lower edge near the base",
      "where": "arising from the dorsal armor plate on the neck just behind and above the head, arching forward over the head"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded furry ears, brown, with dense fur",
      "where": "on the top sides of the bear head, one on each side, partially under the edge of a dark triangular head plate"
    },
    {
      "part": "legs",
      "looks_like": "four thick, columnar legs encased in overlapping glossy dark brown segmented plates with small spiny points along the rear edges; the plates form rings around the limbs",
      "where": "under the body, two front legs under the chest and two hind legs under the rear, supporting the body in a standing posture"
    },
    {
      "part": "feet",
      "looks_like": "four broad feet covered on top with dark plates, each ending in several long curved dark claws",
      "where": "at the bottom ends of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "short to medium tapering tail made of overlapping dark plates forming rings that get smaller toward a pointed tip",
      "where": "at the rear end of the body, extending down and slightly back from the hindquarters"
    },
    {
      "part": "shell",
      "looks_like": "extensive glossy exoskeleton forming a hard covering over the back, neck, sides and limbs, dark brown to black and shiny",
      "where": "covering the entire torso from behind the head to the tail, wrapping around the sides and over the shoulders and hips"
    },
    {
      "part": "plates",
      "looks_like": "numerous overlapping hard plates; large smooth dorsal plates along the back, smaller pointed plates on the legs, lighter brown segmented plates on the belly, and a row of vertical slit-like openings with dotted interiors and spiral structures below them along the lower side",
      "where": "dorsal plates along the mid-back, lateral plates on the sides with the slit openings, ventral plates on the underside/belly, and ring-like plates encircling each leg and the tail; a small triangular plate sits on the forehead between the ears"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "rhinoceros beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
